#!/usr/bin/env bash
# tunnelbot one-file installer, version 2026.10.17.6.
# Upload it to the server (SFTP) and run:   bash tunnelbot-setup.sh
# The same file updates an existing install (settings are kept).  Options: --reconfigure, --help
# TB_EXTRACT_TO=<dir> only unpacks the files there (nothing is installed).
case "$(head -c 16384 "$0" 2>/dev/null | tr -dc '\r' | wc -c)" in 0) ;; *) T=$(mktemp /tmp/tunnelbot-setup-lf.XXXXXX) || exit 1; tr -d '\r' < "$0" > "$T" || exit 1; echo "note: the file arrived with Windows line endings (text-mode upload); using a repaired copy" >&2; bash "$T" "$@"; rc=$?; rm -f "$T"; exit $rc;; esac #
grep -q '^__TUNNELBOT_PAYLOAD__$' "$0" 2>/dev/null || { echo "ERROR: the file is incomplete — upload it again" >&2; exit 1; } #
set -euo pipefail
SHA256=0719475cac206efb90d4b02c7f8b87458f4c2bd5bd96c24d9a3185612c6a340e
SELF=$(readlink -f "$0")
LINE=$(awk '/^__TUNNELBOT_PAYLOAD__$/ { print NR + 1; exit }' "$SELF")
[ -n "$LINE" ] || { echo "ERROR: the file is incomplete — upload it again" >&2; exit 1; }
GOT=$(tail -n +"$LINE" "$SELF" | sha256sum | cut -d' ' -f1)
[ "$GOT" = "$SHA256" ] || { echo "ERROR: the file is incomplete or damaged (checksum mismatch) — upload it again" >&2; exit 1; }
if [ -n "${TB_EXTRACT_TO:-}" ]; then
  mkdir -p "$TB_EXTRACT_TO"
  tail -n +"$LINE" "$SELF" | base64 -d | tar -xz -C "$TB_EXTRACT_TO"
  echo "extracted to $TB_EXTRACT_TO/tunnelbot"
  exit 0
fi
if [ "$(id -u)" != 0 ]; then
  command -v sudo >/dev/null 2>&1 || { echo "ERROR: run it as root" >&2; exit 1; }
  exec sudo -E bash "$SELF" "$@"
fi
TMP=$(mktemp -d /tmp/tunnelbot-setup.XXXXXX)
trap 'rm -rf "$TMP"' EXIT
tail -n +"$LINE" "$SELF" | base64 -d | tar -xz -C "$TMP"
set +e
bash "$TMP/tunnelbot/install.sh" "$@"
exit $?
